T:u" id="Seg_2312" s="T180" e="T182"><nts n="HIAT:ip" id="Seg_2313">¡</nts><ts n="HIAT:w" id="Seg_2315" s="T180" e="T181.TIE0.1">Buenos</ts><nts n="HIAT:ip" id="Seg_2316"><![CDATA[ ]]></nts><ts n="HIAT:w" id="Seg_2318" s="T181.TIE0.1" e="T182">días</ts><nts n="HIAT:ip" id="Seg_2319">!</nts><nts n="HIAT:ip" id="Seg_2320"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE0"><ts n="sc" id="Seg_2321" s="T2" e="T4"><ts n="e" id="Seg_2323" s="T2" e="T3">¡Hola! </ts><ts n="e" id="Seg_2325" s="T3" e="T4">¡Buenos días! </ts></ts><ts n="sc" id="Seg_2326" s="T5" e="T7"><ts n="e" id="Seg_2328" s="T5" e="T6">• • </ts><ts n="e" id="Seg_2330" s="T6" e="T7">¡Muchas gracias! </ts></ts><ts n="sc" id="Seg_2331" s="T8" e="T14"><ts n="e" id="Seg_2333" s="T8" e="T9">• • </ts><ts n="e" id="Seg_2335" s="T9" e="T10">((ríe)) La curva del Pardo es una curva de la/ </ts><ts n="e" id="Seg_2337" s="T10" e="T11">del hipódromo de la Zarzuela en/ en Madrid. </ts><ts n="e" id="Seg_2339" s="T11" e="T12">((inspira)) </ts><ts n="e" id="Seg_2341" s="T12" e="T13">Yyy, en fin, eh para los hípicos tiene mucho significado lo </ts><ts n="e" id="Seg_2343" s="T13" e="T14">que supongo (que) para los demás no les suena nada especial. </ts></ts><ts n="sc" id="Seg_2344" s="T16" e="T18"><ts n="e" id="Seg_2346" s="T16" e="T17">• • </ts><ts n="e" id="Seg_2348" s="T17" e="T18">Sí sí! </ts></ts><ts n="sc" id="Seg_2349" s="T21" e="T31"><ts n="e" id="Seg_2351" s="T21" e="T22">No </ts><ts n="e" id="Seg_2353" s="T22" e="T23">tiene/ no tiene templarios, </ts><ts n="e" id="Seg_2355" s="T23" e="T24">no tiene sectas. </ts><ts n="e" id="Seg_2357" s="T24" e="T25">((rí</ts><ts n="e" id="Seg_2359" s="T25" e="T26">e, 1,3s)) </ts><ts n="e" id="Seg_2361" s="T26" e="T27">Pues sí, es un poco atípica. </ts><ts n="e" id="Seg_2363" s="T27" e="T28">Pero a lo mejor la gente ya está un poco cansada </ts><ts n="e" id="Seg_2365" s="T28" e="T29">de todas esas cosas, y y quiere cambiar, </ts><ts n="e" id="Seg_2367" s="T29" e="T30">yo tengo la esperenza que quiera cambiar. </ts><ts n="e" id="Seg_2369" s="T30" e="T31">((inspira)) </ts></ts><ts n="sc" id="Seg_2370" s="T38" e="T58"><ts n="e" id="Seg_2372" s="T38" e="T39">• • </ts><ts n="e" id="Seg_2374" s="T39" e="T40">((inspira)) </ts><ts n="e" id="Seg_2376" s="T40" e="T41">Bueno hom… </ts><ts n="e" id="Seg_2378" s="T41" e="T42">mmm, de todo… </ts><ts n="e" id="Seg_2380" s="T42" e="T43">((ríe)) </ts><ts n="e" id="Seg_2382" s="T43" e="T44">(E gira) • el/ e la/ </ts><ts n="e" id="Seg_2384" s="T44" e="T45">todo gira en torno a una gran carrera de caballos </ts><ts n="e" id="Seg_2386" s="T45" e="T46">donde dos magnates que se odian cordialmente pues </ts><ts n="e" id="Seg_2388" s="T46" e="T47">((inspira)) e quieren dividir sus/ em sus odios/ </ts><ts n="e" id="Seg_2390" s="T47" e="T48">e m cada uno con sus caballos. </ts><ts n="e" id="Seg_2392" s="T48" e="T49">((inspira)) </ts><ts n="e" id="Seg_2394" s="T49" e="T50">Y el caballo más importante </ts><ts n="e" id="Seg_2396" s="T50" e="T51">— el mejor de todos — pues ee </ts><ts n="e" id="Seg_2398" s="T51" e="T52">• </ts><ts n="e" id="Seg_2400" s="T52" e="T53">necesita un jinete determinado que lo monte porque es el único que lo entiende bien. </ts><ts n="e" id="Seg_2402" s="T53" e="T54">((inspira)) </ts><ts n="e" id="Seg_2404" s="T54" e="T55">Y este jinete ha desaparecido. </ts><ts n="e" id="Seg_2406" s="T55" e="T56">Entonces hay que buscar a ese jinete. </ts><ts n="e" id="Seg_2408" s="T56" e="T57">((inspira)) </ts><ts n="e" id="Seg_2410" s="T57" e="T58">Y un poco en eso trata la novela. </ts></ts><ts n="sc" id="Seg_2411" s="T64" e="T69"><ts n="e" id="Seg_2413" s="T64" e="T65">((inspira)) </ts><ts n="e" id="Seg_2415" s="T65" e="T66">¡Sí, eso es! </ts><ts n="e" id="Seg_2417" s="T66" e="T67">((inspira)) </ts><ts n="e" id="Seg_2419" s="T67" e="T68">Bueno el/ </ts><ts n="e" id="Seg_2421" s="T68" e="T69">es una novela… </ts></ts><ts n="sc" id="Seg_2422" s="T70" e="T107"><ts n="e" id="Seg_2424" s="T70" e="T71">• • </ts><ts n="e" id="Seg_2426" s="T71" e="T72">Bueno, e… </ts><ts n="e" id="Seg_2428" s="T72" e="T73">Hombre e e… </ts><ts n="e" id="Seg_2430" s="T73" e="T74">• • </ts><ts n="e" id="Seg_2432" s="T74" e="T75">Nooo/ no hay que asustarse. </ts><ts n="e" id="Seg_2434" s="T75" e="T76">No es/ no </ts><ts n="e" id="Seg_2436" s="T76" e="T77">es una novela de </ts><ts n="e" id="Seg_2438" s="T77" e="T78">filosofía, ni bien… </ts><ts n="e" id="Seg_2440" s="T78" e="T79">Pero bueno yo creo que cada uno </ts><ts n="e" id="Seg_2442" s="T79" e="T80">• • </ts><ts n="e" id="Seg_2444" s="T80" e="T81">ya … </ts><ts n="e" id="Seg_2446" s="T81" e="T82">• • </ts><ts n="e" id="Seg_2448" s="T82" e="T83">en fin el lector lo verá… </ts><ts n="e" id="Seg_2450" s="T83" e="T84">((inspira)) </ts><ts n="e" id="Seg_2452" s="T84" e="T85">Como la novela está narrada a varias voces, </ts><ts n="e" id="Seg_2454" s="T85" e="T86">o sea hay varios personajes que cuentan cada uno </ts><ts n="e" id="Seg_2456" s="T86" e="T87">su perspectiva sobre lo que está ocurriendo, </ts><ts n="e" id="Seg_2458" s="T87" e="T88">((inspira)) </ts><ts n="e" id="Seg_2460" s="T88" e="T89">cada uno de los personajes está por un lao contando lo que pasa </ts><ts n="e" id="Seg_2462" s="T89" e="T90">((inspira)) </ts><ts n="e" id="Seg_2464" s="T90" e="T91">y por otro </ts><ts n="e" id="Seg_2466" s="T91" e="T92">lao </ts><ts n="e" id="Seg_2468" s="T92" e="T93">contando lo que le pasa a él: </ts><ts n="e" id="Seg_2470" s="T93" e="T94">• • </ts><ts n="e" id="Seg_2472" s="T94" e="T95">sus sueños, sus miedos, sus frustraciones, </ts><ts n="e" id="Seg_2474" s="T95" e="T96">sus/ ((inspira)) sus </ts><ts n="e" id="Seg_2476" s="T96" e="T97">nostalgias </ts><ts n="e" id="Seg_2478" s="T97" e="T98">etcétera ¿no? </ts><ts n="e" id="Seg_2480" s="T98" e="T99">Entonces… </ts><ts n="e" id="Seg_2482" s="T99" e="T100">((inspira)) </ts><ts n="e" id="Seg_2484" s="T100" e="T101">E a la vez • están interviniendo en la acción </ts><ts n="e" id="Seg_2486" s="T101" e="T102">como protagonistas, </ts><ts n="e" id="Seg_2488" s="T102" e="T103">y también rememorando y recordando </ts><ts n="e" id="Seg_2490" s="T103" e="T104">pues lo que es su vida ¿no? </ts><ts n="e" id="Seg_2492" s="T104" e="T105">((inspira)) </ts><ts n="e" id="Seg_2494" s="T105" e="T106">Entonces eso/ eso/ esa rememoración </ts><ts n="e" id="Seg_2496" s="T106" e="T107">pues tiene eso, pues un poquito de aliño metafísico. </ts></ts><ts n="sc" id="Seg_2497" s="T114" e="T146"><ts n="e" id="Seg_2499" s="T114" e="T115">No no sí, no/ yo vi/ </ts><ts n="e" id="Seg_2501" s="T115" e="T116">mi/ mi campo </ts><ts n="e" id="Seg_2503" s="T116" e="T117">es el ensayo, es el artículo, no sé. </ts><ts n="e" id="Seg_2505" s="T117" e="T118">Yo esto me ha venido/ • • me ha venido muy bien </ts><ts n="e" id="Seg_2507" s="T118" e="T119">porque durante un año muy complicado como ha sido este </ts><ts n="e" id="Seg_2509" s="T119" e="T120">que en fin si se recuerda </ts><ts n="e" id="Seg_2511" s="T120" e="T121">pues hemos lanzao un partido político nuevo. </ts><ts n="e" id="Seg_2513" s="T121" e="T122">((inspira)) </ts><ts n="e" id="Seg_2515" s="T122" e="T123">Hemos afrontao unas elecciones </ts><ts n="e" id="Seg_2517" s="T123" e="T124">sin poca o/ o ninguna ayuda </ts><ts n="e" id="Seg_2519" s="T124" e="T125">de medios y de bancos y de tal. </ts><ts n="e" id="Seg_2521" s="T125" e="T126">((inspira)) </ts><ts n="e" id="Seg_2523" s="T126" e="T127">Hemos lograo tener una parlamentaria. </ts><ts n="e" id="Seg_2525" s="T127" e="T128">Yo he dao mi último curso en la facultad </ts><ts n="e" id="Seg_2527" s="T128" e="T129">porque este año ha sido el de mi jubilación. </ts><ts n="e" id="Seg_2529" s="T129" e="T130">((inspira)) </ts><ts n="e" id="Seg_2531" s="T130" e="T131">Eeh mmm eh mmm </ts><ts n="e" id="Seg_2533" s="T131" e="T132">nos hemos lanzado el manifiesto de la lengua común </ts><ts n="e" id="Seg_2535" s="T132" e="T133">que termina teniendo bastante polémica. </ts><ts n="e" id="Seg_2537" s="T133" e="T134">Y es decir yo (creo que ha sido) un año bastante cargado de acontecimientos. </ts><ts n="e" id="Seg_2539" s="T134" e="T135">((inspira)) </ts><ts n="e" id="Seg_2541" s="T135" e="T136">Entonces eh la novela me servía para refugiarme, </ts><ts n="e" id="Seg_2543" s="T136" e="T137">para escaparme ¿no? </ts><ts n="e" id="Seg_2545" s="T137" e="T138">Eran mis vacaciones diarias. </ts><ts n="e" id="Seg_2547" s="T138" e="T139">((inspira)) </ts><ts n="e" id="Seg_2549" s="T139" e="T140">Me iba una hora o dos horas a mi mundo especial </ts><ts n="e" id="Seg_2551" s="T140" e="T141">privado de/ ((inspira)) de esa novela. </ts><ts n="e" id="Seg_2553" s="T141" e="T142">Y ahí me refugiaba y se me olvidaba durante un rato </ts><ts n="e" id="Seg_2555" s="T142" e="T143">todo lo que estaba pasando y/ </ts><ts n="e" id="Seg_2557" s="T143" e="T144">((inspira)) </ts><ts n="e" id="Seg_2559" s="T144" e="T145">y me ha venido muy bien. </ts><ts n="e" id="Seg_2561" s="T145" e="T146">Y ojalá que a algún lector le sirva para lo mismo ¿no? </ts></ts><ts n="sc" id="Seg_2562" s="T147" e="T166"><ts n="e" id="Seg_2564" s="T147" e="T148">((inspira)) </ts><ts n="e" id="Seg_2566" s="T148" e="T149">• • </ts><ts n="e" id="Seg_2568" s="T149" e="T150">Bueno yo creo que la ética es una reflexión sobre nuestra libertad </ts><ts n="e" id="Seg_2570" s="T150" e="T151">• </ts><ts n="e" id="Seg_2572" s="T151" e="T152">y la filosofía pues de alguna manera es una reflexión sobre nuestra vida. </ts><ts n="e" id="Seg_2574" s="T152" e="T153">((inspira)) </ts><ts n="e" id="Seg_2576" s="T153" e="T154">Yyy hombre me parece que </ts><ts n="e" id="Seg_2578" s="T154" e="T155">siempre — sobre todo cuando estamos mmm eh comoo </ts><ts n="e" id="Seg_2580" s="T155" e="T156">dicen tiempos turbulentos — </ts><ts n="e" id="Seg_2582" s="T156" e="T157">es bueno reflexionar sobre lo que nos pasa, </ts><ts n="e" id="Seg_2584" s="T157" e="T158">sobre lo que queremos hacer. </ts><ts n="e" id="Seg_2586" s="T158" e="T159">((inspira)) </ts><ts n="e" id="Seg_2588" s="T159" e="T160">(Es decir) </ts><ts n="e" id="Seg_2590" s="T160" e="T161">en vez de dejarnos siempre arrastrar por los acontecimientos </ts><ts n="e" id="Seg_2592" s="T161" e="T162">y seguir el el el/ la corriente pues, </ts><ts n="e" id="Seg_2594" s="T162" e="T163">mmm mmm también decidir </ts><ts n="e" id="Seg_2596" s="T163" e="T164">qué es lo que vamos a hacer y qué preferimos nosotros. </ts><ts n="e" id="Seg_2598" s="T164" e="T165">((inspira)) </ts><ts n="e" id="Seg_2600" s="T165" e="T166">Y qué/ como ser protagonista de nuestra vida ¿no? </ts></ts><ts n="sc" id="Seg_2601" s="T168" e="T169"><ts n="e" id="Seg_2603" s="T168" e="T169">((inc.))˙ </ts></ts><ts n="sc" id="Seg_2604" s="T170" e="T171"><ts n="e" id="Seg_2606" s="T170" e="T171">Eh˙ </ts></ts><ts n="sc" id="Seg_2607" s="T172" e="T173"><ts n="e" id="Seg_2609" s="T172" e="T173">Eh˙ </ts></ts><ts n="sc" id="Seg_2610" s="T174" e="T182"><ts n="e" id="Seg_2612" s="T174" e="T175">¡Muy bien! </ts><ts n="e" id="Seg_2614" s="T175" e="T176">¡Gracias </ts><ts n="e" id="Seg_2616" s="T176" e="T177">a vosotros! </ts><ts n="e" id="Seg_2618" s="T177" e="T178">¿E? </ts><ts n="e" id="Seg_2620" s="T178" e="T179">¡Adiós! </ts><ts n="e" id="Seg_2622" s="T179" e="T180">¡Buenos días! </ts><ts n="e" id="Seg_2624" s="T180" e="T181">¡Buen</ts><ts n="e" id="Seg_2626" s="T181" e="T182">os días! </ts></ts></segmentation><annotation name="akz" tierref="TIE1"><ta id="Seg_2627" s="T96" e="T97">—</ta></annotation><annotation name="en" tierref="TIE2"><ta id="Seg_2628" s="T2" e="T3">Hello! </ta><ta id="Seg_2629" s="T3" e="T4">Good day! </ta><ta id="Seg_2630" s="T5" e="T6">• • </ta><ta id="Seg_2631" s="T6" e="T7">Thank you very much! </ta><ta id="Seg_2632" s="T8" e="T9">• • </ta><ta id="Seg_2633" s="T9" e="T11">((laughs)) The Pardo's Curve is a curve of the/ of the race-course of the Zarzuela in/ in Madrid. </ta><ta id="Seg_2634" s="T11" e="T12">((breathes)) </ta><ta id="Seg_2635" s="T12" e="T14">Aaand, finally, for horse enthusiasts this place is very significant, which I assume for other people doesn't mean anything special. </ta><ta id="Seg_2636" s="T16" e="T17">• • </ta><ta id="Seg_2637" s="T17" e="T18">Yes, yes! </ta><ta id="Seg_2638" s="T21" e="T23">It doens't have / it doesn't have Templars, </ta><ta id="Seg_2639" s="T23" e="T24">it doesn't have sects. </ta><ta id="Seg_2640" s="T24" e="T25">((laugh</ta><ta id="Seg_2641" s="T25" e="T26">s, 1,3s)) </ta><ta id="Seg_2642" s="T26" e="T27">Yes indeed, it's somewhat atypical. </ta><ta id="Seg_2643" s="T27" e="T29">But perhaps people are already a bit tired of all those things, and and they want to change, </ta><ta id="Seg_2644" s="T29" e="T30">I hope to change them. </ta><ta id="Seg_2645" s="T30" e="T31">((breathes)) </ta><ta id="Seg_2646" s="T38" e="T39">• • </ta><ta id="Seg_2647" s="T39" e="T40">((breathes)) </ta><ta id="Seg_2648" s="T40" e="T41">Well, Sir... </ta><ta id="Seg_2649" s="T41" e="T42"> ehm, anyway... </ta><ta id="Seg_2650" s="T42" e="T43">((laughs)) </ta><ta id="Seg_2651" s="T43" e="T44">(Eh it centers) • / it/ eh it/ </ta><ta id="Seg_2652" s="T44" e="T46">anyway, it centers on a big horse-race where two moguls who hate each other with all their hearts </ta><ta id="Seg_2653" s="T46" e="T48">((breathes)) eh want to share their/ em their hatreds/ each one with their horses. </ta><ta id="Seg_2654" s="T48" e="T49">((breathes)) </ta><ta id="Seg_2655" s="T49" e="T50">And the most important horse </ta><ta id="Seg_2656" s="T50" e="T51">— the best one of all — well eeh </ta><ta id="Seg_2657" s="T51" e="T52">• </ta><ta id="Seg_2658" s="T52" e="T53">needs a determined jockey who mounts it, because he is the only one who understands it. </ta><ta id="Seg_2659" s="T53" e="T54">((breathes)) </ta><ta id="Seg_2660" s="T54" e="T55">And this jockey has disappeared. </ta><ta id="Seg_2661" s="T55" e="T56">That's why this jockey has to be found. </ta><ta id="Seg_2662" s="T56" e="T57">((breathes)) </ta><ta id="Seg_2663" s="T57" e="T58">And that is sort of how this novel goes. </ta><ta id="Seg_2664" s="T64" e="T65">((breathes)) </ta><ta id="Seg_2665" s="T65" e="T66">Yes, that' it! </ta><ta id="Seg_2666" s="T66" e="T67">((breathes)) </ta><ta id="Seg_2667" s="T67" e="T68">Well the/ </ta><ta id="Seg_2668" s="T68" e="T69">it's a novel... </ta><ta id="Seg_2669" s="T70" e="T71">• • </ta><ta id="Seg_2670" s="T71" e="T72">Well eh... </ta><ta id="Seg_2671" s="T72" e="T73">Sir eh eh... </ta><ta id="Seg_2672" s="T73" e="T74">• • </ta><ta id="Seg_2673" s="T74" e="T75">You don't/ don't have to get frightened.</ta><ta id="Seg_2674" s="T75" e="T78">It isn't/ isn't a philosophical novel nor well... </ta><ta id="Seg_2675" s="T78" e="T79">But, well, I think that every one </ta><ta id="Seg_2676" s="T79" e="T80">• • </ta><ta id="Seg_2677" s="T80" e="T81">well... </ta><ta id="Seg_2678" s="T81" e="T82">• • </ta><ta id="Seg_2679" s="T82" e="T83">finally the reader will see it... </ta><ta id="Seg_2680" s="T83" e="T84">((breathes)) </ta><ta id="Seg_2681" s="T84" e="T85">Since the novel is narrated by various voices, </ta><ta id="Seg_2682" s="T85" e="T86">this means different characters tell one by one </ta><ta id="Seg_2683" s="T86" e="T87">their perpective about what is happening </ta><ta id="Seg_2684" s="T87" e="T88">((breathes)) </ta><ta id="Seg_2685" s="T88" e="T89">each one of the characters is telling on one side what happens </ta><ta id="Seg_2686" s="T89" e="T90">((breathes)) </ta><ta id="Seg_2687" s="T90" e="T93">and on the other side is telling what happens to him: </ta><ta id="Seg_2688" s="T93" e="T94">• • </ta><ta id="Seg_2689" s="T94" e="T95">his dreams, his fears, his frustrations, </ta><ta id="Seg_2690" s="T95" e="T98">his/ ((breathes)) his aspirations and so on, right? </ta><ta id="Seg_2691" s="T98" e="T99">That's why... </ta><ta id="Seg_2692" s="T99" e="T100">((breathes)) </ta><ta id="Seg_2693" s="T100" e="T102">And at the same time • they are intervening in the action as main characters, </ta><ta id="Seg_2694" s="T102" e="T104">and also remembering and recalling well what is his life, right? </ta><ta id="Seg_2695" s="T104" e="T105">((breathes)) </ta><ta id="Seg_2696" s="T105" e="T106">That's why this/ this/ this rememberance </ta><ta id="Seg_2697" s="T106" e="T107">well, has this, well, a bit of metaphysical flavour. </ta><ta id="Seg_2698" s="T114" e="T115">No no yes, no/ I saw/ </ta><ta id="Seg_2699" s="T115" e="T116">my/ my field </ta><ta id="Seg_2700" s="T116" e="T117">is the essay, is the article, I don't know.</ta><ta id="Seg_2701" s="T117" e="T118">I, this did/ • • did me lots of good </ta><ta id="Seg_2702" s="T118" e="T119">because during a very complicated year as this one has been </ta><ta id="Seg_2703" s="T119" e="T120">which, well, if you remember </ta><ta id="Seg_2704" s="T120" e="T121">well we placed on the market a new political party. </ta><ta id="Seg_2705" s="T121" e="T122">((breathes)) </ta><ta id="Seg_2706" s="T122" e="T123">We had to affront some elections </ta><ta id="Seg_2707" s="T123" e="T124">with few or/ or no help </ta><ta id="Seg_2708" s="T124" e="T125">from media and from banks and from such things. </ta><ta id="Seg_2709" s="T125" e="T126">((breathes)) </ta><ta id="Seg_2710" s="T126" e="T127">We achieved to have a parlamentarian. </ta><ta id="Seg_2711" s="T127" e="T129">And I gave my last course in the faculty because this year has been the one of my retirement. </ta><ta id="Seg_2712" s="T129" e="T130">((breathes)) </ta><ta id="Seg_2713" s="T130" e="T131">Ehm mmm eh ehm </ta><ta id="Seg_2714" s="T131" e="T133">we haved placed on the market the manifest of the common language which finally got much polemics. </ta><ta id="Seg_2715" s="T133" e="T134">And which means I (think it has been) a year quite charged with events. </ta><ta id="Seg_2716" s="T134" e="T135">((breathes)) </ta><ta id="Seg_2717" s="T135" e="T136">That's why ehm the novel served me to flee, </ta><ta id="Seg_2718" s="T136" e="T137">to escape, right? </ta><ta id="Seg_2719" s="T137" e="T138">These were my daily holidays. </ta><ta id="Seg_2720" s="T138" e="T139">((breathes)) </ta><ta id="Seg_2721" s="T139" e="T141">I went to my special private world of/ ((breathes)) of that novel for one hour or two hours. </ta><ta id="Seg_2722" s="T141" e="T142">And there I escaped and I forgot for a while </ta><ta id="Seg_2723" s="T142" e="T143">everything that had happened and/ </ta><ta id="Seg_2724" s="T143" e="T144">((breathes)) </ta><ta id="Seg_2725" s="T144" e="T145">and it did me lots of good. </ta><ta id="Seg_2726" s="T145" e="T146">And hopefully it will do the same thing to some reader, won't it? </ta><ta id="Seg_2727" s="T147" e="T148">((breathes)) </ta><ta id="Seg_2728" s="T148" e="T149">• • </ta><ta id="Seg_2729" s="T149" e="T150">Well, I think ethics is a reflection about our freedom </ta><ta id="Seg_2730" s="T150" e="T151">• </ta><ta id="Seg_2731" s="T151" e="T152">and philosophy is somehow a reflection about our life.</ta><ta id="Seg_2732" s="T152" e="T153">((breathes)) </ta><ta id="Seg_2733" s="T153" e="T154">Aaand, Sir, it appears to me that </ta><ta id="Seg_2734" s="T154" e="T156">always — especially when we are like they say in turbulent times — </ta><ta id="Seg_2735" s="T156" e="T157">it is good to think about what happens to us, </ta><ta id="Seg_2736" s="T157" e="T158">about what we want to do. </ta><ta id="Seg_2737" s="T158" e="T159">((breathes)) </ta><ta id="Seg_2738" s="T159" e="T160">(Which means) </ta><ta id="Seg_2739" s="T160" e="T162">instead of being always dragged by the events and following the the the/ the current, </ta><ta id="Seg_2740" s="T162" e="T163">ehmehm also decide </ta><ta id="Seg_2741" s="T163" e="T164">what is the thing we want to do and prefer. </ta><ta id="Seg_2742" s="T164" e="T165">((breathes)) </ta><ta id="Seg_2743" s="T165" e="T166">And what/ like beeing the main character of our life, isn't it? </ta><ta id="Seg_2744" s="T168" e="T169">((inc.))˙ </ta><ta id="Seg_2745" s="T170" e="T171">Eh˙ </ta><ta id="Seg_2746" s="T172" e="T173">Eh˙ </ta><ta id="Seg_2747" s="T174" e="T175">Very good!</ta><ta id="Seg_2748" s="T175" e="T177">Thanks to you!</ta><ta id="Seg_2749" s="T177" e="T178">OK? </ta><ta id="Seg_2750" s="T178" e="T179">Goodbye!</ta><ta id="Seg_2751" s="T179" e="T180">Good day!</ta><ta id="Seg_2752" s="T180" e="T182">Good day!</ta></annotation></segmented-tier><segmented-tier id="TIE3" speaker="SPK1" category="v" type="t" display-name="LR [v]"><timeline-fork start="T1" end="T2"><tli id="T1.TIE3.1"/>
