id="Seg_3512"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE3"><ts n="sc" id="Seg_3513" s="T1" e="T2"><ts n="e" id="Seg_3515" s="T1" e="T2">¡Fernando Savater, buenos días! </ts></ts><ts n="sc" id="Seg_3516" s="T4" e="T5"><ts n="e" id="Seg_3518" s="T4" e="T5">¡Enhorabuena! </ts></ts><ts n="sc" id="Seg_3519" s="T7" e="T8"><ts n="e" id="Seg_3521" s="T7" e="T8">¿La curva del Pardo es esa dónde se ve a la señora? </ts></ts><ts n="sc" id="Seg_3522" s="T14" e="T16"><ts n="e" id="Seg_3524" s="T14" e="T15">Bueno, estaba pensando en esa leyenda urbana. </ts><ts n="e" id="Seg_3526" s="T15" e="T16">¿Pero la cosa va de hípica? </ts></ts><ts n="sc" id="Seg_3527" s="T17" e="T22"><ts n="e" id="Seg_3529" s="T17" e="T18">En/ • </ts><ts n="e" id="Seg_3531" s="T18" e="T19">en esta novela que mmm </ts><ts n="e" id="Seg_3533" s="T19" e="T20">((inspira)) no tiene • • catedrales, no tiene guerras. </ts><ts n="e" id="Seg_3535" s="T20" e="T21">No sé si va a ser un éxito </ts><ts n="e" id="Seg_3537" s="T21" e="T22">¿eh? </ts></ts><ts n="sc" id="Seg_3538" s="T24" e="T25"><ts n="e" id="Seg_3540" s="T24" e="T25">((ríe))˙ </ts></ts><ts n="sc" id="Seg_3541" s="T31" e="T38"><ts n="e" id="Seg_3543" s="T31" e="T32">La Hermandad de la Buena Suerte… </ts><ts n="e" id="Seg_3545" s="T32" e="T33">mmm </ts><ts n="e" id="Seg_3547" s="T33" e="T34">((inspira)) </ts><ts n="e" id="Seg_3549" s="T34" e="T35">• • </ts><ts n="e" id="Seg_3551" s="T35" e="T36">mmm˙ </ts><ts n="e" id="Seg_3553" s="T36" e="T37">• • • </ts><ts n="e" id="Seg_3555" s="T37" e="T38">¿Qué hacen los caballos en esta obra? </ts></ts><ts n="sc" id="Seg_3556" s="T58" e="T64"><ts n="e" id="Seg_3558" s="T58" e="T59">• • • </ts><ts n="e" id="Seg_3560" s="T59" e="T60">Es una novela — Usted mismo lo ha dicho —</ts><ts n="e" id="Seg_3562" s="T60" e="T61">y además me parece la definición — </ts><ts n="e" id="Seg_3564" s="T61" e="T62">((inspira)) </ts><ts n="e" id="Seg_3566" s="T62" e="T63">eh si me permite — muy inteligente, </ts><ts n="e" id="Seg_3568" s="T63" e="T64">una obra de aventuras con un poquito de aliño metafísico. </ts></ts><ts n="sc" id="Seg_3569" s="T68" e="T70"><ts n="e" id="Seg_3571" s="T68" e="T69">¡Dígame Usted lo que es el </ts><ts n="e" id="Seg_3573" s="T69" e="T70">aliño metafísico! </ts></ts><ts n="sc" id="Seg_3574" s="T76" e="T77"><ts n="e" id="Seg_3576" s="T76" e="T77">((rié))˙ </ts></ts><ts n="sc" id="Seg_3577" s="T107" e="T115"><ts n="e" id="Seg_3579" s="T107" e="T108">Ha escrito más de cuarenta y cinco </ts><ts n="e" id="Seg_3581" s="T108" e="T109">• libros </ts><ts n="e" id="Seg_3583" s="T109" e="T110">entre ellos desde luego esa ((inspira)) eh imprescindible </ts><ts n="e" id="Seg_3585" s="T110" e="T111">y que es libro de cabecera para muchos padres que quieren ser educadores es "Ética para Amador". </ts><ts n="e" id="Seg_3587" s="T111" e="T112">((inspira)) </ts><ts n="e" id="Seg_3589" s="T112" e="T113">Eh mmm ¿va a darle más a la novela </ts><ts n="e" id="Seg_3591" s="T113" e="T114">o va seguir centrado en la </ts><ts n="e" id="Seg_3593" s="T114" e="T115">ética (en las relaciones)? </ts></ts><ts n="sc" id="Seg_3594" s="T146" e="T148"><ts n="e" id="Seg_3596" s="T146" e="T147">¿La ética y la filosofía pueden ser un buen punto de apoyo en estos tiempos tur</ts><ts n="e" id="Seg_3598" s="T147" e="T148">bulentos? </ts></ts><ts n="sc" id="Seg_3599" s="T166" e="T174"><ts n="e" id="Seg_3601" s="T166" e="T167">((inspira)) </ts><ts n="e" id="Seg_3603" s="T167" e="T168">¡Fernando Savater, muchisimas gracias al </ts><ts n="e" id="Seg_3605" s="T168" e="T169">Premio </ts><ts n="e" id="Seg_3607" s="T169" e="T170">Plan</ts><ts n="e" id="Seg_3609" s="T170" e="T171">eta </ts><ts n="e" id="Seg_3611" s="T171" e="T172">por com</ts><ts n="e" id="Seg_3613" s="T172" e="T173">partir </ts><ts n="e" id="Seg_3615" s="T173" e="T174">este tiempo con los oyentes de Radio Nacional! </ts></ts><ts n="sc" id="Seg_3616" s="T176" e="T177"><ts n="e" id="Seg_3618" s="T176" e="T177">¡Buenos días! </ts></ts><ts n="sc" id="Seg_3619" s="T178" e="T181"><ts n="e" id="Seg_3621" s="T178" e="T179">((inc.))˙ </ts><ts n="e" id="Seg_3623" s="T179" e="T181">((inc.))˙ </ts></ts></segmentation><annotation name="en" tierref="TIE4"><ta id="Seg_3624" s="T1" e="T2">Fernando Savater, good day! </ta><ta id="Seg_3625" s="T4" e="T5">Congratulation! </ta><ta id="Seg_3626" s="T7" e="T8">The Pardo's Curve, is this the place where the woman is seen? </ta><ta id="Seg_3627" s="T14" e="T15">Well, I was thinking of that urban legend. </ta><ta id="Seg_3628" s="T15" e="T16">But the thing is about equitation? </ta><ta id="Seg_3629" s="T17" e="T18">In/ • </ta><ta id="Seg_3630" s="T18" e="T19">in this novel, which ehm </ta><ta id="Seg_3631" s="T19" e="T20">((breathes)) doesn't have • • cathedrals, doesn't have wars. </ta><ta id="Seg_3632" s="T20" e="T21">I don't know if it will be a success, </ta><ta id="Seg_3633" s="T21" e="T22">you know? </ta><ta id="Seg_3634" s="T24" e="T25">((laughs))˙ </ta><ta id="Seg_3635" s="T31" e="T32">The Brotherhood of the Good Luck... </ta><ta id="Seg_3636" s="T32" e="T33">ehm </ta><ta id="Seg_3637" s="T33" e="T34">((breathes)) </ta><ta id="Seg_3638" s="T34" e="T35">• • </ta><ta id="Seg_3639" s="T35" e="T36">ehm˙ </ta><ta id="Seg_3640" s="T36" e="T37">• • • </ta><ta id="Seg_3641" s="T37" e="T38">What do the horses do in this work? </ta><ta id="Seg_3642" s="T58" e="T59">• • • </ta><ta id="Seg_3643" s="T59" e="T60">It is a novel — you said it yourself — </ta><ta id="Seg_3644" s="T60" e="T61">and additionally I think the definition — </ta><ta id="Seg_3645" s="T61" e="T62">((breathes)) </ta><ta id="Seg_3646" s="T62" e="T63">eh if you allow me — very intelligent, </ta><ta id="Seg_3647" s="T63" e="T64">a work of adventures with a little metaphysical flavor. </ta><ta id="Seg_3648" s="T68" e="T70">Tell me what is the metaphysical flavor! </ta><ta id="Seg_3649" s="T76" e="T77">((laughs))˙ </ta><ta id="Seg_3650" s="T107" e="T108">You have written more than fourty-five </ta><ta id="Seg_3651" s="T108" e="T109">• books </ta><ta id="Seg_3652" s="T109" e="T110">among them of course, this ((breathes)) eh indispensable one </ta><ta id="Seg_3653" s="T110" e="T111">and which is a bedside book for many parents who want to be educators is "Esthics for Amador". </ta><ta id="Seg_3654" s="T111" e="T112">((breathes)) </ta><ta id="Seg_3655" s="T112" e="T115">Em, em are you going to add something more to this novel or are you going to continue centered on the ethics (in the relations)? </ta><ta id="Seg_3656" s="T146" e="T148">Can ethics and philosophy be a good point of support in these turbulent times? </ta><ta id="Seg_3657" s="T166" e="T167">((breathes)) </ta><ta id="Seg_3658" s="T167" e="T174">Fernando Savater, thank you very much to the winner of the Planeta Price for spending this time with the audience of Radio Nacional! </ta><ta id="Seg_3659" s="T176" e="T177">Good day! </ta><ta id="Seg_3660" s="T178" e="T179">((inc.))˙ </ta><ta id="Seg_3661" s="T179" e="T181">((inc.))˙ </ta></annotation></segmented-tier></segmented-body><conversion-info><basic-transcription-conversion-info><conversion-timeline><conversion-tli id="T0"/><conversion-tli id="T1"/><conversion-tli id="T2"/><conversion-tli id="T3"/><conversion-tli id="T4"/><conversion-tli id="T5"/><conversion-tli id="T6"/><conversion-tli id="T7"/><conversion-tli id="T8"/><conversion-tli id="T9"/><conversion-tli id="T10"/><conversion-tli id="T11"/><conversion-tli id="T12"/><conversion-tli id="T13"/><conversion-tli id="T14"/><conversion-tli id="T15"/><conversion-tli id="T16"/><conversion-tli id="T17"/><conversion-tli id="T18"/><conversion-tli id="T19"/><conversion-tli id="T20"/><conversion-tli id="T21"/><conversion-tli id="T22"/><conversion-tli id="T23"/><conversion-tli id="T24"/><conversion-tli id="T25"/><conversion-tli id="T26"/><conversion-tli id="T27"/><conversion-tli id="T28"/><conversion-tli id="T29"/><conversion-tli id="T30"/><conversion-tli id="T31"/><conversion-t